#include <stdio.h>
#include <string.h>

void aEtiqueta(void) {
    char nome[50] = "";
    int idade = 0;
    scanf("%49s", nome);
    scanf("%d", &idade);
    char etiqueta[60] = "";
    snprintf(etiqueta, sizeof etiqueta, "Nome: %s | Idade: %d", nome, idade);
    int tamanho = strlen(etiqueta);
    printf("%s\n", etiqueta);
    printf("%d\n", tamanho);
}
